// This file is part of the uutils coreutils package.
//
// For the full copyright and license information, please view the LICENSE
// file that was distributed with this source code.

// spell-checker:ignore (ToDO) allocs bset dflag cflag sflag tflag

mod operation;

use clap::{crate_version, value_parser, Arg, ArgAction, Command};
use operation::{BadSequence, Class, Sequence};
use std::collections::{HashMap, HashSet};
use std::ffi::OsString;
use std::io::{stdin, stdout, BufRead, BufWriter, Write};
use uucore::{format_usage, help_about, help_section, help_usage, os_str_as_bytes, show};

use uucore::display::Quotable;
use uucore::error::{UResult, USimpleError, UUsageError};

const ABOUT: &str = help_about!("tr.md");
const AFTER_HELP: &str = help_section!("after help", "tr.md");
const USAGE: &str = help_usage!("tr.md");

mod options {
    pub const COMPLEMENT: &str = "complement";
    pub const DELETE: &str = "delete";
    pub const SQUEEZE: &str = "squeeze-repeats";
    pub const TRUNCATE_SET1: &str = "truncate-set1";
    pub const SETS: &str = "sets";
}

#[uucore::main]
pub fn uumain(args: impl uucore::Args) -> UResult<()> {
    let matches = uu_app().after_help(AFTER_HELP).try_get_matches_from(args)?;

    let delete_flag = matches.get_flag(options::DELETE);
    let complement_flag = matches.get_flag(options::COMPLEMENT);
    let squeeze_flag = matches.get_flag(options::SQUEEZE);
    let truncate_set1_flag = matches.get_flag(options::TRUNCATE_SET1);

    // Ultimately this should be OsString, but we might want to wait for the
    // pattern API on OsStr
    let sets: Vec<_> = matches
        .get_many::<OsString>(options::SETS)
        .into_iter()
        .flatten()
        .map(ToOwned::to_owned)
        .collect();

    let sets_len = sets.len();

    if sets.is_empty() {
        return Err(UUsageError::new(1, "missing operand"));
    }

    if !(delete_flag || squeeze_flag) && sets_len < 2 {
        return Err(UUsageError::new(
            1,
            format!(
                "missing operand after {}\nTwo strings must be given when translating.",
                sets[0].quote()
            ),
        ));
    }

    if delete_flag & squeeze_flag && sets_len < 2 {
        return Err(UUsageError::new(
            1,
            format!(
                "missing operand after {}\nTwo strings must be given when deleting and squeezing.",
                sets[0].quote()
            ),
        ));
    }

    if sets_len > 1 {
        let start = "extra operand";
        if delete_flag && !squeeze_flag {
            let op = sets[1].quote();
            let msg = if sets_len == 2 {
                format!(
                    "{} {}\nOnly one string may be given when deleting without squeezing repeats.",
                    start, op,
                )
            } else {
                format!("{} {}", start, op,)
            };
            return Err(UUsageError::new(1, msg));
        }
        if sets_len > 2 {
            let op = sets[2].quote();
            let msg = format!("{} {}", start, op);
            return Err(UUsageError::new(1, msg));
        }
    }

    if let Some(first) = sets.first() {
        let slice = os_str_as_bytes(first)?;

        let mut iter = slice.iter();

        if let Some(b'\\') = iter.next_back() {
            match iter.next_back() {
                Some(b'\\') => {
                    // The trailing backslash has a backslash preceding it, so it is properly escaped
                }
                _ => {
                    // The trailing backslash has a non-backslash character before it OR is the only character in the
                    // string, so the warning applies
                    show!(USimpleError::new(
                        0,
                        "warning: an unescaped backslash at end of string is not portable"
                    ));
                }
            }
        }
    }

    let stdin = stdin();
    let mut locked_stdin = stdin.lock();
    let stdout = stdout();
    let locked_stdout = stdout.lock();
    let mut buffered_stdout = BufWriter::new(locked_stdout);

    // According to the man page: translating only happens if deleting or if a second set is given
    let translating = !delete_flag && sets.len() > 1;
    let mut sets_iter = sets.iter().map(|c| c.as_os_str());
    let set1_raw = os_str_as_bytes(sets_iter.next().unwrap_or_default())?;
    let set2_raw = os_str_as_bytes(sets_iter.next().unwrap_or_default())?;
    let truncate_set1_now = truncate_set1_flag && translating;

    let set1_seq = Sequence::from_str(set1_raw)?;
    for seq in &set1_seq {
        if let Sequence::CharStar(_) = seq {
            return Err(BadSequence::CharRepeatInSet1.into());
        }
    }

    let mut set2_seq = Sequence::from_str(set2_raw)?;
    let mut set2_star_count = 0usize;
    for seq in &set2_seq {
        if let Sequence::CharStar(_) = seq {
            set2_star_count += 1;
            if set2_star_count > 1 {
                return Err(BadSequence::MultipleCharRepeatInSet2.into());
            }
        }
    }

    if translating {
        for seq in &set2_seq {
            if let Sequence::Class(class) = seq {
                match class {
                    Class::Upper | Class::Lower => {}
                    _ => {
                        return Err(BadSequence::ClassExceptLowerUpperInSet2.into());
                    }
                }
            }
        }
    }

    let mut set1_solved: Vec<u8> = Vec::new();
    for seq in &set1_seq {
        set1_solved.extend(seq.flatten());
    }

    if complement_flag {
        let mut complemented = Vec::new();
        let mut candidate = 0u16;
        while candidate <= u8::MAX as u16 {
            let byte = candidate as u8;
            if !set1_solved.contains(&byte) {
                complemented.push(byte);
            }
            candidate += 1;
        }
        set1_solved = complemented;
    }
    let set1_len = set1_solved.len();

    let set2_len = set2_seq
        .iter()
        .filter_map(|seq| match seq {
            Sequence::CharStar(_) => None,
            other => Some(other),
        })
        .flat_map(Sequence::flatten)
        .count();
    let star_compensate_len = set1_len.saturating_sub(set2_len);
    set2_seq = set2_seq
        .iter()
        .filter_map(|seq| match seq {
            Sequence::CharStar(0) => None,
            Sequence::CharStar(c) => Some(Sequence::CharRepeat(*c, star_compensate_len)),
            other => Some(*other),
        })
        .collect();

    for (set2_pos, set2_item) in set2_seq.iter().enumerate() {
        if let Sequence::Class(_) = set2_item {
            let mut set2_part_solved_len = 0usize;
            if set2_pos >= 1 {
                set2_part_solved_len = set2_seq
                    .iter()
                    .take(set2_pos)
                    .flat_map(Sequence::flatten)
                    .count();
            }

            let mut class_matches = false;
            for (set1_pos, set1_item) in set1_seq.iter().enumerate() {
                if let Sequence::Class(_) = set1_item {
                    let mut set1_part_solved_len = 0usize;
                    if set1_pos >= 1 {
                        set1_part_solved_len = set1_seq
                            .iter()
                            .take(set1_pos)
                            .flat_map(Sequence::flatten)
                            .count();
                    }
                    if set1_part_solved_len == set2_part_solved_len {
                        class_matches = true;
                        break;
                    }
                }
            }

            if !class_matches {
                return Err(BadSequence::ClassInSet2NotMatchedBySet1.into());
            }
        }
    }

    let mut set2_solved: Vec<u8> = Vec::new();
    for seq in &set2_seq {
        set2_solved.extend(seq.flatten());
    }

    let mut set2_uniques = set2_solved.clone();
    set2_uniques.sort();
    set2_uniques.dedup();

    let set1_has_class = set1_seq
        .iter()
        .any(|item| matches!(item, Sequence::Class(_)));
    if set1_has_class && translating && complement_flag {
        if set2_uniques.len() > 1 || set2_solved.len() > set1_len {
            return Err(BadSequence::ComplementMoreThanOneUniqueInSet2.into());
        }
    }

    if set2_solved.len() < set1_solved.len() && !truncate_set1_now {
        match set2_seq.last().copied() {
            Some(Sequence::Class(Class::Upper)) | Some(Sequence::Class(Class::Lower)) => {
                return Err(BadSequence::Set1LongerSet2EndsInClass.into());
            }
            _ => {}
        }
    }

    if truncate_set1_now {
        set1_solved.truncate(set2_solved.len());
    }

    let mut translation_map: HashMap<u8, u8> = HashMap::new();
    if translating {
        if let Some(fallback) = set2_solved.last().copied() {
            for (index, source) in set1_solved.iter().copied().enumerate() {
                if index < set2_solved.len() {
                    translation_map.insert(source, set2_solved[index]);
                } else {
                    translation_map.insert(source, fallback);
                }
            }
        } else if set1_solved.is_empty() && set2_solved.is_empty() {
            translation_map.clear();
        } else {
            return Err(BadSequence::EmptySet2WhenNotTruncatingSet1.into());
        }
    }

    let squeeze_source = if delete_flag {
        set2_solved.clone()
    } else if squeeze_flag {
        if sets_len < 2 {
            set1_solved.clone()
        } else {
            set2_solved.clone()
        }
    } else {
        Vec::new()
    };
    let squeeze_set: HashSet<u8> = squeeze_source.into_iter().collect();
    let mut squeeze_prev: Option<u8> = None;
    let mut buf = Vec::new();
    let mut output_buf = Vec::new();

    while let Ok(length) = locked_stdin.read_until(b'\n', &mut buf) {
        if length == 0 {
            break;
        } else {
            for &current in buf.iter() {
                if delete_flag {
                    if !set1_solved.contains(&current) {
                        if squeeze_flag {
                            if squeeze_set.contains(&current) {
                                if let Some(prev) = squeeze_prev {
                                    output_buf.extend(
                                        std::iter::once(current)
                                            .take((prev != current) as usize),
                                    );
                                } else {
                                    output_buf.push(current);
                                }
                            } else {
                                output_buf.push(current);
                            }
                            squeeze_prev = Some(current);
                        } else {
                            output_buf.push(current);
                        }
                    }
                } else {
                    let mapped = if translating {
                        translation_map.get(&current).copied().unwrap_or(current)
                    } else {
                        current
                    };
                    if squeeze_flag {
                        if squeeze_set.contains(&mapped) {
                            if let Some(prev) = squeeze_prev {
                                output_buf.extend(
                                    std::iter::once(mapped).take((prev != mapped) as usize),
                                );
                            } else {
                                output_buf.push(mapped);
                            }
                        } else {
                            output_buf.push(mapped);
                        }
                        squeeze_prev = Some(mapped);
                    } else {
                        output_buf.push(mapped);
                    }
                }
            }
            buffered_stdout.write_all(&output_buf).unwrap();
        }
        buf.clear();
        output_buf.clear();
    }
    Ok(())
}

pub fn uu_app() -> Command {
    Command::new(uucore::util_name())
        .version(crate_version!())
        .about(ABOUT)
        .override_usage(format_usage(USAGE))
        .infer_long_args(true)
        .trailing_var_arg(true)
        .arg(
            Arg::new(options::COMPLEMENT)
                .visible_short_alias('C')
                .short('c')
                .long(options::COMPLEMENT)
                .help("use the complement of SET1")
                .action(ArgAction::SetTrue)
                .overrides_with(options::COMPLEMENT),
        )
        .arg(
            Arg::new(options::DELETE)
                .short('d')
                .long(options::DELETE)
                .help("delete characters in SET1, do not translate")
                .action(ArgAction::SetTrue)
                .overrides_with(options::DELETE),
        )
        .arg(
            Arg::new(options::SQUEEZE)
                .long(options::SQUEEZE)
                .short('s')
                .help(
                    "replace each sequence of a repeated character that is \
                     listed in the last specified SET, with a single occurrence \
                     of that character",
                )
                .action(ArgAction::SetTrue)
                .overrides_with(options::SQUEEZE),
        )
        .arg(
            Arg::new(options::TRUNCATE_SET1)
                .long(options::TRUNCATE_SET1)
                .short('t')
                .help("first truncate SET1 to length of SET2")
                .action(ArgAction::SetTrue)
                .overrides_with(options::TRUNCATE_SET1),
        )
        .arg(
            Arg::new(options::SETS)
                .num_args(1..)
                .value_parser(value_parser!(OsString)),
        )
}

